# 1. 钻石继承：super() 沿 MRO 调度
class A:
    def __init__(self):
        print("A.__init__")
        super().__init__()

class B(A):
    def __init__(self):
        print("B.__init__")
        super().__init__()

class C(A):
    def __init__(self):
        print("C.__init__")
        super().__init__()

class D(B, C):
    def __init__(self):
        print("D.__init__")
        super().__init__()

D()  # 输出: D B C A （每个类只调一次）
print("MRO:", [c.__name__ for c in D.__mro__])
# MRO: ['D', 'B', 'C', 'A', 'object']

# 2. 类变量遮蔽
class Counter:
    count = 0  # 类变量

a = Counter()
b = Counter()
a.count += 1   # 等价于 a.count = a.count + 1 → 创建实例变量，类变量不变
print(a.count)  # 1 (实例变量)
print(b.count)  # 0 (类变量)
print(Counter.count)  # 0

Counter.count += 1  # 真正修改类变量
print(b.count)  # 1

# 3. classmethod 工厂
class Date:
    def __init__(self, year, month, day):
        self.year, self.month, self.day = year, month, day

    @classmethod
    def from_string(cls, s):
        y, m, d = s.split("-")
        return cls(int(y), int(m), int(d))  # cls 动态指向调用类

    def __repr__(self):
        return f"{self.year}-{self.month:02d}-{self.day:02d}"

print(Date.from_string("2025-01-15"))  # 2025-01-15

# 4. 鸭子类型
class Duck:
    def quack(self): return "嘎嘎"

class Person:
    def quack(self): return "学鸭子叫"

def make_it_quack(thing):
    print(thing.quack())  # 不关心 thing 的类型

make_it_quack(Duck())    # 嘎嘎
make_it_quack(Person())  # 学鸭子叫
